style.css:
/* ♡ MOE PASTEL FONT THEME ♡ */
/* Soft pink text — no background changes */

/* Main font */
html,
body,
body * {
  font-family: "Nunito", "Trebuchet MS", sans-serif !important;
}

/* Soft pastel text */
body,
p,
span,
li,
label,
td,
th,
small,
div {
  color: #e5b4cd;
}

/* Headings — delicate blush pink */
h1,
h2,
h3,
h4,
h5,
h6 {
  color: #e8a3c4 !important;
  font-weight: 600 !important;
  letter-spacing: 0.4px;
}

/* Links */
a {
  color: #e6a9c8 !important;
  text-decoration-color: #f5d2e4 !important;
  transition: color 0.2s ease;
}

a:hover {
  color: #f0bfd8 !important;
}

/* Input text */
input,
textarea,
select,
button {
  font-family: "Nunito", "Trebuchet MS", sans-serif !important;
}

/* Placeholder text */
input::placeholder,
textarea::placeholder {
  color: #dfbfd0 !important;
}

/* Selection */
::selection {
  background: #f9dfec !important;
  color: #b77f9c !important;
}
